CREATE TABLE camp_review (
  review_id INTEGER PRIMARY KEY,
  student_id INTEGER NOT NULL,
  stars INTEGER CHECK (stars BETWEEN 1 AND 5),
  memo TEXT DEFAULT '없음',
  FOREIGN KEY (student_id) REFERENCES students(student_id)
);
INSERT INTO camp_review (review_id, student_id, stars) VALUES (1, 5, 4);
ALTER TABLE camp_review ADD camp_name TEXT;
SELECT * FROM camp_review;

MERGE INTO camp_signup t
USING (SELECT 4 AS student_id, 'AI캠프' AS camp_name FROM dual) s
ON (t.student_id = s.student_id AND t.camp_name = s.camp_name)
WHEN MATCHED THEN UPDATE SET t.status = '확정'
WHEN NOT MATCHED THEN INSERT (signup_id, student_id, camp_name, status)
  VALUES (5, s.student_id, s.camp_name, '신청');
GRANT SELECT ON camp_signup TO teacher;
REVOKE SELECT ON camp_signup FROM teacher;
TRUNCATE TABLE camp_signup;
